              <i className="ph-bold ph-pen-nib text-xl"></i>
            </div>
            <span className="text-xl font-bold text-slate-800 tracking-tight">พู่กันไฟ <span className="gradient-text">Ultimate</span></span>
          </div>
          {/* API Status Indicator */}
          <div id="api-status" className={`text-xs font-medium px-3 py-1 rounded-full flex items-center gap-1 transition-colors duration-300 neumorphic-btn ${apiReady ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
            <i className="ph-fill ph-circle text-xs"></i>
            <span id="api-status-text">{apiReady ? 'API พร้อมใช้งาน' : 'API Key ไม่พร้อม'}</span>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-6xl mx-auto p-4 md:p-6 space-y-8 pb-32">
