            <button onClick={() => setActiveVisualTab('video')} className={`flex-1 py-4 px-4 font-medium flex justify-center gap-2 items-center transition-all ${activeVisualTab === 'video' ? 'neumorphic-tab-active' : 'neumorphic-tab'}`}>
