        <span className="tooltip">{isSpeaking ? 'หยุดอ่าน' : 'อ่านข้อความที่เลือก'}</span>
        <button id="stt-btn" className="fab-btn group" onClick={() => alert("STT not implemented in React demo")}><i className="ph-bold ph-microphone text-xl"></i></button>
        <span className="tooltip">สั่งงานด้วยเสียง</span>
      </div>

    </div>
  );
};

