  // --- State for Tabs ---
  const [activeVisualTab, setActiveVisualTab] = useState<'image' | 'video'>('image');
  const [activeCreativeTab, setActiveCreativeTab] = useState<'char' | 'editor'>('char');

  // --- State for Inputs ---
  const [inputs, setInputs] = useState({
