  const [charVoice, setCharVoice] = useState('Kore');

  // --- State for Results (HTML strings for markdown) ---
  const [results, setResults] = useState<{ [key: string]: string | null }>({});
  const [loading, setLoading] = useState<{ [key: string]: boolean }>({});
