            min-height: 100vh;
            margin: 0;
            transition: all 0.3s ease;
            /* Ensure the body can contain the full-screen iframe content */
            width: 100vw;
            height: 100vh;
        }

        /* Neumorphic Utilities */
        .neu-flat {
            border-radius: 20px;
            background: var(--bg-color);
            box-shadow: 9px 9px 16px rgb(163,177,198,0.6), 
