        }

        .neu-btn {
            border-radius: 50px;
            background: var(--bg-color);
            box-shadow: 6px 6px 10px 0 rgba(163,177,198, 0.7), 
                       -6px -6px 10px 0 rgba(255,255,255, 0.8);
            color: var(--accent);
            font-weight: 600;
            transition: all 0.2s ease;
            cursor: pointer;
            border: none;
            outline: none;
        }

        .neu-btn:active {
            box-shadow: inset 4px 4px 6px 0 rgba(163,177,198, 0.7), 
                        inset -4px -4px 6px 0 rgba(255,255,255, 0.8);
            transform: translateY(1px);
        }

        .neu-btn:hover {
            color: #5b4cc4;
        }

        /* Card Hover Effect */
        .tool-card {
            transition: transform 0.3s ease;
        }
        .tool-card:hover {
            transform: translateY(-5px);
        }

        /* Inputs */
        input {
            width: 100%;
            padding: 12px 20px;
            border: none;
            outline: none;
            color: var(--text-main);
            background: transparent;
        }

        /* Animation */
        .fade-in {
            animation: fadeIn 0.5s ease-in-out;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .hidden {
            display: none !important;
        }

        .toast {
            position: fixed;
            top: 20px;
            left: 50%;
            transform: translateX(-50%);
            padding: 10px 20px;
            border-radius: 50px;
            background: var(--bg-color);
            box-shadow: 5px 5px 10px #babecc, -5px -5px 10px #ffffff;
            color: var(--accent);
            font-weight: bold;
            z-index: 1000;
            opacity: 0;
            transition: opacity 0.3s;
            pointer-events: none;
        }
        .toast.show {
            opacity: 1;
        }

        /* Full screen iframe container */
        #toolEmbedSection {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            z-index: 50; /* Above other content */
            background-color: var(--bg-color);
            display: flex;
            flex-direction: column;
        }

        #toolEmbedSection iframe {
            flex-grow: 1; /* Make iframe fill available space */
            border: none;
            width: 100%;
            height: 100%;
        }

        /* Ensure main container handles fixed elements well */
        #mainContainerWrapper {
            width: 100%;
            height: 100%;
            display: flex;
            justify-content: center;
            align-items: center;
            position: relative;
            z-index: 10;
        }

        /* Adjust container max-width to not conflict with fullscreen tools */
        .container {
            max-width: 48rem; /* default max-w-4xl */
            height: auto;
            min-height: 100vh;
            padding: 20px;
        }

    </style>
</head>
<body>

    <!-- Toast Notification -->
    <div id="toast" class="toast">แจ้งเตือน</div>

    <!-- Full-screen Tool Embed Section (Initially Hidden) -->
    <div id="toolEmbedSection" class="hidden">
        <!-- Header for Embedded Tool View -->
        <div id="toolHeader" class="flex justify-between items-center neu-flat px-6 py-3 w-full">
            <!-- Back Button to Dashboard -->
            <button onclick="goBackToDashboard()" class="neu-btn w-10 h-10 rounded-full flex items-center justify-center text-gray-700 hover:text-gray-900">
                <i class="fa-solid fa-arrow-left"></i>
            </button>
            <h2 id="toolTitle" class="font-bold text-lg text-[#4d4d4d] truncate"></h2>
            <!-- Logout Button -->
            <button onclick="logout()" class="neu-btn w-10 h-10 rounded-full flex items-center justify-center text-red-400 hover:text-red-600">
                <i class="fa-solid fa-power-off"></i>
            </button>
        </div>

        <!-- Iframe for AI Ultimate Pro -->
        <iframe id="toolIframe1" src="https://ai-ultimate.vercel.app/writer-studio.html/#" class="hidden" title="AI Ultimate Pro" loading="lazy"></iframe>

        <!-- Iframe for Writer Flow AI -->
        <iframe id="toolIframe2" src="https://writer-flow-ai.vercel.app/#" class="hidden" title="Writer Flow AI" loading="lazy"></iframe>
    </div>

    <!-- Main Container Wrapper (for Auth and Dashboard views) -->
    <div id="mainContainerWrapper" class="container mx-auto px-4 max-w-4xl">

        <!-- SECTION 1: AUTHENTICATION (Login / Register) -->
        <div id="authSection" class="neu-flat p-8 md:p-12 max-w-md mx-auto fade-in">
            <div class="text-center mb-8">
                <div class="w-20 h-20 mx-auto neu-flat rounded-full flex items-center justify-center mb-4 text-3xl text-[#6d5dfc]">
                    <i class="fa-solid fa-user-astronaut"></i>
                </div>
                <h1 class="text-2xl font-bold text-[#4d4d4d]" id="authTitle">เข้าสู่ระบบ</h1>
                <p class="text-sm text-gray-500 mt-2">เพื่อเข้าใช้งาน AI Tools Portal</p>
            </div>

            <form id="authForm" class="space-y-6">
                <div class="neu-pressed rounded-full px-4 py-1">
                    <input type="text" id="username" placeholder="ชื่อผู้ใช้งาน (Username)" required autocomplete="off">
                </div>
                <div class="neu-pressed rounded-full px-4 py-1">
                    <input type="password" id="password" placeholder="รหัสผ่าน (Password)" required>
                </div>

                <button type="submit" class="neu-btn w-full py-3 mt-4 text-lg">
                    <span id="btnText">เข้าสู่ระบบ</span>
                </button>
            </form>

            <div class="mt-6 text-center text-sm text-gray-500">
                <span id="toggleText">ยังไม่มีบัญชีใช่ไหม?</span>
                <button id="toggleAuth" class="text-[#6d5dfc] font-bold ml-1 hover:underline bg-transparent border-none cursor-pointer">ลงทะเบียน</button>
            </div>
        </div>

        <!-- SECTION 2: PORTAL DASHBOARD (Hidden by default) -->
        <div id="dashboardSection" class="hidden fade-in w-full">
            <!-- Header -->
            <div class="flex justify-between items-center mb-10 neu-flat px-6 py-4 rounded-full">
                <div class="flex items-center gap-3">
                    <div class="w-10 h-10 neu-flat rounded-full flex items-center justify-center text-[#6d5dfc]">
                        <i class="fa-solid fa-robot"></i>
                    </div>
                    <div>
                        <h2 class="font-bold text-lg leading-tight">AI Portal</h2>
                        <p class="text-xs text-gray-500">ยินดีต้อนรับ, <span id="userDisplay">User</span></p>
                    </div>
                </div>
                <button onclick="logout()" class="neu-btn w-10 h-10 rounded-full flex items-center justify-center text-red-400 hover:text-red-600">
                    <i class="fa-solid fa-power-off"></i>
                </button>
            </div>

            <!-- Grid Cards -->
            <div class="grid grid-cols-1 md:grid-cols-2 gap-8">

                <!-- Tool 1: AI Ultimate Pro (Click Handler) -->
                <!-- เมื่อกดแล้วจะเรียก showTool('tool1', 'AI Ultimate Pro') เพื่อแสดง iframe -->
                <div onclick="showTool('tool1', 'AI Ultimate Pro')" class="neu-flat p-8 tool-card h-full flex flex-col items-center text-center cursor-pointer group">
                    <div class="w-24 h-24 neu-flat rounded-full flex items-center justify-center text-4xl text-blue-500 mb-6 group-hover:text-blue-600 transition-colors">
                        <i class="fa-solid fa-pen-nib"></i>
                    </div>
                    <h3 class="text-xl font-bold mb-2">AI Ultimate Pro</h3>
                    <p class="text-sm text-gray-500 mb-6">เครื่องมือช่วยเขียน Writer Studio ระดับมืออาชีพ ปลดล็อคทุกจินตนาการ</p>
                    <div class="neu-btn px-6 py-2 text-sm mt-auto">
                        เข้าใช้งาน <i class="fa-solid fa-arrow-right ml-2"></i>
                    </div>
                </div>

                <!-- Tool 2: Writer Flow AI (Click Handler) -->
                <!-- เมื่อกดแล้วจะเรียก showTool('tool2', 'Writer Flow AI') เพื่อแสดง iframe -->
                <div onclick="showTool('tool2', 'Writer Flow AI')" class="neu-flat p-8 tool-card h-full flex flex-col items-center text-center cursor-pointer group">
                    <div class="w-24 h-24 neu-flat rounded-full flex items-center justify-center text-4xl text-purple-500 mb-6 group-hover:text-purple-600 transition-colors">
                        <i class="fa-solid fa-wand-magic-sparkles"></i>
                    </div>
                    <h3 class="text-xl font-bold mb-2">Writer Flow AI</h3>
                    <p class="text-sm text-gray-500 mb-6">สร้างสรรค์เนื้อหาลื่นไหลไม่มีสะดุด ด้วยพลัง AI อัจฉริยะ</p>
                    <div class="neu-btn px-6 py-2 text-sm mt-auto">
                        เข้าใช้งาน <i class="fa-solid fa-arrow-right ml-2"></i>
                    </div>
                </div>

            </div>

            <footer class="text-center text-gray-400 text-xs mt-12">
                &copy; 2024 AI Tools Portal. All rights reserved.
            </footer>
        </div>

    </div>

    <script>
        // DOM Elements
        const authSection = document.getElementById('authSection');
        const dashboardSection = document.getElementById('dashboardSection');
        const toolEmbedSection = document.getElementById('toolEmbedSection');
        const toolHeader = document.getElementById('toolHeader');
        const toolTitle = document.getElementById('toolTitle');
        const toolIframe1 = document.getElementById('toolIframe1');
        const toolIframe2 = document.getElementById('toolIframe2');

        // Auth Elements (re-used)
        const authForm = document.getElementById('authForm');
        const authTitle = document.getElementById('authTitle');
        const btnText = document.getElementById('btnText');
        const toggleText = document.getElementById('toggleText');
        const toggleAuthBtn = document.getElementById('toggleAuth');
        const usernameInput = document.getElementById('username');
        const passwordInput = document.getElementById('password');
        const userDisplay = document.getElementById('userDisplay');
        const toast = document.getElementById('toast');

        // State
        let isLoginMode = true;

        // Check Login Status on Load
        window.addEventListener('load', () => {
            const currentUser = localStorage.getItem('portalUser');
            if (currentUser) {
                showDashboard(currentUser);
            }
        });

        // Toggle Login / Register
        toggleAuthBtn.addEventListener('click', (e) => {
            e.preventDefault();
            isLoginMode = !isLoginMode;
            updateAuthUI();
        });

        function updateAuthUI() {
            if (isLoginMode) {
                authTitle.innerText = "เข้าสู่ระบบ";
                btnText.innerText = "เข้าสู่ระบบ";
                toggleText.innerText = "ยังไม่มีบัญชีใช่ไหม?";
                toggleAuthBtn.innerText = "ลงทะเบียน";
            } else {
                authTitle.innerText = "ลงทะเบียนใหม่";
                btnText.innerText = "ยืนยันการลงทะเบียน";
                toggleText.innerText = "มีบัญชีอยู่แล้ว?";
                toggleAuthBtn.innerText = "เข้าสู่ระบบ";
            }
            authForm.reset();
        }

        // Handle Form Submit
        authForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const username = usernameInput.value.trim();
            const password = passwordInput.value.trim();

            if (!username || !password) {
                showToast("กรุณากรอกข้อมูลให้ครบถ้วน");
                return;
            }

            if (isLoginMode) {
                // Login Logic (Simulated using localStorage)
                const storedUser = localStorage.getItem('registered_' + username);
                if (storedUser && storedUser === password) {
                    localStorage.setItem('portalUser', username);
                    showToast("เข้าสู่ระบบสำเร็จ!");
                    setTimeout(() => showDashboard(username), 1000);
                } else {
                    showToast("ชื่อผู้ใช้หรือรหัสผ่านไม่ถูกต้อง");
                }
            } else {
                // Register Logic (Simulated using localStorage)
                if (localStorage.getItem('registered_' + username)) {
                    showToast("ชื่อผู้ใช้นี้ถูกใช้งานแล้ว");
                } else {
                    localStorage.setItem('registered_' + username, password);
                    showToast("ลงทะเบียนสำเร็จ! กรุณาเข้าสู่ระบบ");
                    // Switch to login mode
                    isLoginMode = true;
                    updateAuthUI();
                    usernameInput.value = username; // Auto fill username
                }
            }
        });

        // Show Dashboard View
        function showDashboard(username) {
            authSection.classList.add('hidden');
            toolEmbedSection.classList.add('hidden');
            dashboardSection.classList.remove('hidden');
            userDisplay.innerText = username;
        }

        // Show Embedded Tool View
        window.showTool = (toolId, title) => {
            dashboardSection.classList.add('hidden');
            toolEmbedSection.classList.remove('hidden');
            toolTitle.innerText = title;

            // Hide all iframes first
            toolIframe1.classList.add('hidden');
            toolIframe2.classList.add('hidden');

            // Show the selected iframe
            if (toolId === 'tool1') {
                toolIframe1.classList.remove('hidden');
            } else if (toolId === 'tool2') {
                toolIframe2.classList.remove('hidden');
            }
        }

        // Go back to the Dashboard
        window.goBackToDashboard = () => {
            const currentUser = localStorage.getItem('portalUser');
            if (currentUser) {
                // Hide iframes and show dashboard
                toolIframe1.classList.add('hidden');
                toolIframe2.classList.add('hidden');
                showDashboard(currentUser);
            } else {
                // Fallback to reload/show auth
                location.reload();
            }
        }

        // Logout
        function logout() {
            localStorage.removeItem('portalUser');
            location.reload();
        }

        // Utility: Toast Notification
        function showToast(message) {
            toast.innerText = message;
            toast.classList.add('show');
            setTimeout(() => {
                toast.classList.remove('show');
            }, 3000);
        }
    </script>
</body>
</html>"

