                                         </td>
                                         <td className="p-3 text-center">
                                             {resetPassTarget === u.email ? (
                                                 <div className="flex items-center gap-1 bg-white p-1 rounded-lg shadow-sm border border-slate-200 absolute right-4 mt-[-20px] z-20 animate-fade-in-up">
