                                             <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold border ${u.role === 'admin' ? 'bg-purple-50 text-purple-600 border-purple-100' : 'bg-green-50 text-green-600 border-green-100'}`}>
                                                 {u.role.toUpperCase()}
