        <div className="absolute top-[20%] right-[-10%] w-[30%] h-[50%] bg-indigo-200/40 rounded-full blur-[100px]"></div>
        <div className="absolute bottom-[-10%] left-[20%] w-[40%] h-[40%] bg-pink-200/30 rounded-full blur-[120px]"></div>
