            >
               <i className="ph-bold ph-sign-out"></i> ออกจากระบบ
            </button>
         </div>
      </div>
    );
  }

  // --- RENDER 3: MAIN APP (DASHBOARD) ---
  return (
    <div className="min-h-screen relative overflow-hidden bg-slate-50 selection:bg-indigo-100 selection:text-indigo-700">

