              className="mt-6 text-xs text-slate-400 hover:text-red-500 flex items-center gap-1"
            >
               <i className="ph-bold ph-sign-out"></i> ออกจากระบบ
            </button>
         </div>
      </div>
    );
  }

  // --- RENDER 3: MAIN APP (DASHBOARD) ---
  return (
